import{_ as t,o as r,c as s,a3 as a}from"./chunks/framework.BwzYn71E.js";const f=JSON.parse('{"title":"优先汇入结构的末端箱子放置顺序影响优先级现象研究","description":"","frontmatter":{"translationSource":{"title":"优先汇入结构的末端箱子放置顺序影响优先级现象研究","archivedAt":"2026-10-31","url":"https://docs.qq.com/aio/DTmluZ1diWlpQZldw?p=3e6Q3Y7LbtinO72F4eucBI","scope":"page"},"translationLang":"zh","head":[["link",{"rel":"canonical","href":"https://kokobird28144.github.io/endfield-skydoc/zh/how-terminal-stash-placement-order-affects-merge-priority"}],["link",{"rel":"alternate","hreflang":"en","href":"https://kokobird28144.github.io/endfield-skydoc/how-terminal-stash-placement-order-affects-merge-priority"}],["link",{"rel":"alternate","hreflang":"zh-CN","href":"https://kokobird28144.github.io/endfield-skydoc/zh/how-terminal-stash-placement-order-affects-merge-priority"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://kokobird28144.github.io/endfield-skydoc/how-terminal-stash-placement-order-affects-merge-priority"}]]},"headers":[],"relativePath":"zh/how-terminal-stash-placement-order-affects-merge-priority.md","filePath":"zh/page-3e6Q3Y7LbtinO72F4eucBI.md"}'),i={name:"zh/how-terminal-stash-placement-order-affects-merge-priority.md"};function c(o,e,l,p,d,n){return r(),s("div",null,[...e[0]||(e[0]=[a('<div class="logistics-content"><h1 id="优先汇入结构的末端箱子放置顺序影响优先级现象研究" tabindex="-1">优先汇入结构的末端箱子放置顺序影响优先级现象研究 <a class="header-anchor" href="#优先汇入结构的末端箱子放置顺序影响优先级现象研究" aria-label="Permalink to &quot;优先汇入结构的末端箱子放置顺序影响优先级现象研究&quot;">​</a></h1><blockquote><p>源页面 ID：<code>3e6Q3Y7LbtinO72F4eucBI</code> ｜ <a href="https://docs.qq.com/aio/DTmluZ1diWlpQZldw?p=3e6Q3Y7LbtinO72F4eucBI" target="_blank" rel="noreferrer">在腾讯文档中打开</a></p></blockquote><p>通常的优先汇入（分流器无其他输出）逻辑如下：在分流器，传送带（非分流器）直接连接汇流器时，先连接优先，非分流器优先时在多个非分流器之间轮询。</p><p>该结构的情况下，修改下游的存储箱的时候，会导致汇流器的优先级发生无法预测的变化，该问题可能是元件计算顺序的问题</p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-687f1d806e3643df.q90-015b4a3b4e20df54.webp" alt="优先汇入结构的末端箱子放置顺序影响优先级现象研究"></p><p>目前暂且将以jnk的层级BFS论可解释的实验结果标记为A，与之相反的结果标记为B，可能需要进一步分类或整合</p><p>根据最新的实验结果，某特定结构（如下图）符合以下规律</p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-961c72e9f7a3366f.png" alt="优先汇入结构的末端箱子放置顺序影响优先级现象研究"></p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-c008e71f938e3bbd.q90-983b9f6c606432d9.webp" alt="优先汇入结构的末端箱子放置顺序影响优先级现象研究"></p><p>新的实验结果说明，可以用以下经验概括</p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-b2de1da8151cc5cb.q90-59f014433854cd20.webp" alt="优先汇入结构的末端箱子放置顺序影响优先级现象研究"></p><p>将红圈结构视为整体，计算出口阻尼，若分流器处阻尼较小（类似高优先）且汇流器下游（紧贴的）物流元件比分流器先放，则成功分流，或者汇流器处阻尼较小且分流器比汇流器上游（紧贴的）物流元件早放，则成功分流，否则不成功，分流器只向汇流器以外的方向输出，可以轮询</p><p>以下是@madSUN 的实验结果</p><p><a href="/endfield-skydoc/logistics/src/assets/attachments/test_priority_with_stash.txt-cd51ebe51ae5a869.txt">附件：test_priority_with_stash.txt</a></p><blockquote><p>原件：test_priority_with_stash.txt；大小：59412；objKey：<code>34fcf9d8c5534f31af9e62daba3e0d0a</code>；本地状态：已下载。</p></blockquote><p>对于该实验结果，jnk如下解释</p><details><summary>群聊聊天记录-解释</summary><p>jnk 2026/6/29 20:29:49<br> 反之c-l在c-r前则分流器先计算阻尼，此时与分流器和汇流器下游连接顺序有关，由分流器主导的，这两个方向中哪个方向先连接则哪个方向先计算，汇流器的另一个上游则总是最后计算，此时若分流器先连接，则计算顺序为“分流器输入-输出-传送带输入”[0]，由于尚未输出就尝试分流器输入，所以分流器无法输入，分流失败，反之分流成功， 从对应三种情况来看，认为放置汇流器时先顺时针连接上游再连接下游[1]<br> &quot;c, c-l, c-r, s&quot;<br> &quot;c-l, c, c-r, s&quot;<br> &quot;c-l, c-r, c, s&quot;</p><p>jnk 2026/6/29 20:29:57<br> 假设[1]是对的，那么此时要求c-l在c-r前的情况分别由于</p><ol><li>c在最后则先连接上游分流器再连接下游传送带</li><li>c-r在最后则已经放下c和s将两者连接，然后再连接c-r下游传送带</li><li>c-l必须在c-r前，所以不能在最后<br> 导致s必须作为结尾</li></ol><p>jnk 2026/6/29 20:30:11<br> 这是剩下九种情况<br> l,r,s,c最后放汇流器导致先连接了分流器再连接下游传送带<br> l,s,r,c<br> s,l,r,c<br> l,s,c,r最后放下游传送带，导致其最后连接<br> l,c,s,r<br> c,l,s,r<br> s,l,c,r<br> c,s,l,r<br> s,c,l,r</p><p>jnk 2026/6/29 20:30:16<br> [0]中提到输入比输出先计算的情况，由4n卡1s的触发条件可以看出这里可以触发4n卡1s现象，通过另一支传送带输入始终为空且分流器的传送带方向输出阻塞无法输出可以构造4n卡1s的出现</p></details></div>',1)])])}const b=t(i,[["render",c]]);export{f as __pageData,b as default};
